
/* ===== app.js ===== */
const DB_KEY='tss_talent_buddy_v1';
const defaultData={requirements:[{id:'TSS001',client:'IntelMacc',title:'Senior Service Manager',location:'Mumbai',experience:'7+ years',industry:'Engineering',status:'Active',skills:['Service Management','Customer Handling','Team Leadership','Escalation Management','CRM'],preferred:['Industrial Automation','Sales Coordination'],qualification:'Engineering / MBA preferred',responsibilities:'Manage service operations, customer escalations, team performance and service delivery.',jdText:'',aiSuggested:false},{id:'TSS002',client:'Neosoft Technologies',title:'ASP.NET Core + Angular Developer',location:'Delhi',experience:'5+ years',industry:'IT',status:'Active',skills:['ASP.NET Core','C#','Angular','REST API','SQL Server'],preferred:['Azure','Git','Entity Framework'],qualification:'B.E./B.Tech/MCA',responsibilities:'Develop enterprise web applications using .NET Core and Angular.',jdText:'',aiSuggested:false},{id:'TSS003',client:'Neosoft Technologies',title:'Database Developer',location:'Delhi',experience:'5+ years',industry:'IT',status:'Active',skills:['MS SQL','MySQL','Stored Procedures','Query Optimization','Database Design'],preferred:['ETL','Performance Tuning'],qualification:'Graduate in CS/IT',responsibilities:'Design, optimize and maintain relational databases.',jdText:'',aiSuggested:false}],candidates:[],screenings:[],activity:[]};
let db=loadDB();
function loadDB(){try{return {...defaultData,...JSON.parse(localStorage.getItem(DB_KEY)||'{}')}}catch(e){return structuredClone(defaultData)}}
function saveDB(){localStorage.setItem(DB_KEY,JSON.stringify(db));renderAll()}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function norm(v=''){return String(v).toLowerCase().replace(/[^a-z0-9+#. ]/g,' ')}
function tokens(v=''){return [...new Set(norm(v).split(/\s+/).filter(x=>x.length>2))]}
function splitSkills(v=''){return [...new Set(String(v).split(/[,;\n|]/).map(x=>x.trim()).filter(Boolean))]}
function esc(v=''){return String(v).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function requirementTimestamp(r={}){const value=r.createdAt||r.created_at||r.submittedAt||r.submitted_at||'';const time=Date.parse(value);return Number.isFinite(time)?time:0}
function requirementNumber(r={}){return Number(String(r.requirementId||r.id||'').match(/\d+/)?.[0]||0)}
function newestRequirements(rows=[]){return rows.slice().sort((a,b)=>requirementTimestamp(b)-requirementTimestamp(a)||requirementNumber(b)-requirementNumber(a)||String(b.requirementId||b.id||'').localeCompare(String(a.requirementId||a.id||'')))}
function activeReqs(){return newestRequirements(db.requirements.filter(r=>['active','work in progress','on hold'].includes(String(r.status||'').trim().toLowerCase())))}
function screeningLabel(score){return score>=75?'Strong Match':score>=50?'Review Recommended':'Not Suitable'}
function statusBadge(label){const cls=label==='Strong Match'?'green':label==='Review Recommended'?'amber':label==='Not Suitable'?'red':'blue';return `<span class="badge ${cls}">${label}</span>`}
function gotoView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===id));const titles={dashboard:'Recruitment Dashboard',requirements:'Job Profiles & JD Intelligence',screening:'New Resume Screening',candidates:'Candidate CV Library',history:'Candidate History'};document.getElementById('pageTitle').textContent=titles[id]||'Talent Buddy'}
document.getElementById('nav').addEventListener('click',e=>{if(e.target.dataset.view){if(e.target.dataset.view==='candidates')candidateReviewOnly=false;gotoView(e.target.dataset.view)}});document.querySelectorAll('[data-open-screening]').forEach(b=>b.onclick=()=>gotoView('screening'));
function calculateExistingMatches(){let n=0;activeReqs().forEach(r=>db.candidates.forEach(c=>{if(scoreCandidate(c.resumeText||'',r,c).score>=55)n++}));return n}
function renderDashboard(){const active=activeReqs(),clients=new Set(active.map(r=>r.client)).size,strong=db.screenings.filter(s=>s.recommendation==='Strong Match').length,review=db.screenings.filter(s=>s.recommendation==='Review Recommended').length,week=Date.now()-7*864e5,newCV=db.candidates.filter(c=>new Date(c.uploadDate).getTime()>week).length,ai=active.filter(r=>r.aiSuggested).length;const stats=[['Active Clients',clients],['Active Requirements',active.length],['Stored Candidates',db.candidates.length],['New CVs This Week',newCV],['Strong Matches',strong],['Needs Review',review],['Existing CV Matches',calculateExistingMatches()],['AI Suggested Skills',ai]];statGrid.innerHTML=stats.map(([a,b])=>`<div class="stat-card"><span>${a}</span><strong>${b}</strong></div>`).join('');const grouped={};active.forEach(r=>(grouped[r.client]??=[]).push(r));requirementsByClient.innerHTML=Object.entries(grouped).map(([c,rs])=>`<div class="client-row"><div><strong>${esc(c)}</strong><small style="display:block;color:var(--muted)">${rs.map(r=>esc(r.title)).join(' • ')}</small></div><span class="badge blue">${rs.length} Active</span></div>`).join('')||'<div class="empty-state">No active requirements</div>';const total=Math.max(db.screenings.length,1),dist=[['Strong Match',strong],['Review Recommended',review],['Not Suitable',db.screenings.filter(s=>s.recommendation==='Not Suitable').length]];matchDistribution.innerHTML=dist.map(([l,n])=>`<div class="bar-row"><div class="bar-label"><span>${l}</span><strong>${n}</strong></div><div class="bar"><i style="width:${Math.round(n/total*100)}%"></i></div></div>`).join('');recentActivity.innerHTML=(db.activity.slice(-6).reverse().map(a=>`<div class="activity-row"><div><strong>${esc(a.title)}</strong><small style="display:block;color:var(--muted)">${esc(a.detail)}</small></div><small>${new Date(a.date).toLocaleDateString()}</small></div>`).join('')||'<div class="empty-state">No activity yet</div>');const incomplete=active.filter(r=>!r.skills?.length||!r.responsibilities).length;alerts.innerHTML=`<div class="alert-row"><span>Requirements without complete JD</span><span class="badge ${incomplete?'amber':'green'}">${incomplete}</span></div><div class="alert-row"><span>Candidates requiring review</span><span class="badge ${review?'amber':'green'}">${review}</span></div><div class="alert-row"><span>Existing CV matches found</span><span class="badge blue">${calculateExistingMatches()}</span></div>`}
function renderSidebar(){const grouped={};activeReqs().forEach(r=>(grouped[r.client]??=[]).push(r));activeRequirementMini.innerHTML=Object.entries(grouped).map(([c,rs])=>`<div class="mini-client"><strong>${esc(c)} · ${rs.length}</strong><small>${rs.map(r=>esc(r.title)).join(', ')}</small></div>`).join('')}
function renderRequirements(){const rows=newestRequirements(db.requirements||[]),signature=JSON.stringify(rows);if(renderRequirements.lastSignature===signature&&requirementCards.children.length===rows.length){window.TSSRequirementStatusVisibility?.applyStatusFilter();return;}renderRequirements.lastSignature=signature;requirementCards.innerHTML=rows.map(r=>`<article class="req-card"><span class="eyebrow">${esc(r.id)} · ${esc(r.client)}</span><h4>${esc(r.title)}</h4><div class="req-meta"><span>${esc(r.location||'Location not set')}</span><span>•</span><span>${esc(r.experience||'Experience not set')}</span><span>•</span>${statusBadge(r.status)}</div><div class="skill-cloud">${(r.skills||[]).map(s=>`<span class="skill ${r.aiSuggested?'ai':''}">${esc(s)}${r.aiSuggested?' · AI':''}</span>`).join('')}</div><small style="color:var(--muted)">${esc(r.responsibilities||'Responsibilities not added')}</small><div class="card-actions"><button class="btn ghost edit-req" data-id="${r.id}">Edit JD</button><button class="btn primary screen-req" data-id="${r.id}">Screen Candidate</button></div></article>`).join('');document.querySelectorAll('.edit-req').forEach(b=>b.onclick=()=>openRequirement(b.dataset.id));document.querySelectorAll('.screen-req').forEach(b=>b.onclick=()=>{screenRequirement.value=b.dataset.id;updateSelectedRequirement();gotoView('screening')});window.TSSRequirementStatusVisibility?.applyStatusFilter()}
function populateScreenReq(){const val=screenRequirement.value;screenRequirement.innerHTML=activeReqs().map(r=>`<option value="${r.id}">${r.id} — ${esc(r.client)} — ${esc(r.title)}</option>`).join('');if(val&&activeReqs().some(r=>r.id===val))screenRequirement.value=val;updateSelectedRequirement()}
function updateSelectedRequirement(){const r=db.requirements.find(x=>x.id===screenRequirement.value);selectedRequirementSummary.innerHTML=r?`<strong>${esc(r.title)}</strong><br><small>${esc(r.client)} · ${esc(r.location)} · ${esc(r.experience)}</small><div class="skill-cloud">${(r.skills||[]).map(s=>`<span class="skill">${esc(s)}</span>`).join('')}</div>`:'No active requirement selected'}screenRequirement.onchange=updateSelectedRequirement;
function candidateDate(value){if(!value)return'Never';const date=new Date(value);return Number.isNaN(date.getTime())?'Never':date.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}
let candidateReviewOnly=false;
function candidateScreenings(c){const ids=new Set([c.id,c.serverId].filter(Boolean).map(String));return(db.screenings||[]).filter(s=>ids.has(String(s.candidateId||s.candidate_id||''))).sort((a,b)=>new Date(a.date||0)-new Date(b.date||0))}
function latestCandidateScreening(c){return candidateScreenings(c).at(-1)||null}
function reviewableCandidateIds(){return new Set((db.candidates||[]).filter(c=>['Strong Match','Review Recommended'].includes(latestCandidateScreening(c)?.recommendation)).flatMap(c=>[c.id,c.serverId]).filter(Boolean).map(String))}
function screeningRequirementLabel(screening){if(!screening)return'';const id=String(screening.requirementId||screening.requirement_id||''),r=(db.requirements||[]).find(x=>[x.id,x.serverId,x.profileKey,x.requirementId].filter(Boolean).map(String).includes(id));return r?[r.client,r.title].filter(Boolean).join(' — '):''}
function showReviewCandidates(){candidateReviewOnly=true;if(candidateSearch)candidateSearch.value='';gotoView('candidates');renderCandidates('')}
function showAllCandidates(){candidateReviewOnly=false;renderCandidates(candidateSearch?.value||'')}
function renderCandidates(filter=''){
  const q=norm(filter),reviewIds=reviewableCandidateIds(),allRows=(db.candidates||[]).filter(c=>!q||norm([c.name,c.email,c.phone,c.designation,c.currentCompany,c.location,c.preferredLocation,c.noticePeriod,(c.skills||[]).join(' ')].join(' ')).includes(q)),rows=candidateReviewOnly?allRows.filter(c=>[c.id,c.serverId].filter(Boolean).some(id=>reviewIds.has(String(id)))):allRows;
  const reviewHead=candidateReviewOnly?`<div class="candidate-review-filter"><div><strong>${rows.length} candidate${rows.length===1?'':'s'} worth reviewing</strong><small>Showing candidates whose latest screening is Strong Match or Review Recommended.</small></div><button type="button" class="btn ghost candidate-clear-review">Show All Candidates</button></div>`:'';
  const table=rows.length?`<div class="candidate-table-scroll"><table class="data-table candidate-records-table"><thead><tr><th>Candidate</th><th>Contact</th><th>Experience</th><th>Location</th><th>Notice</th><th>Last Screened</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>{const history=candidateScreenings(c),last=history.at(-1),role=screeningRequirementLabel(last),hasResume=Boolean(c.resumeAvailable||c.resumePath||c.resumeVersionId),experience=c.totalExperience!==''&&c.totalExperience!=null?`${esc(c.totalExperience)} yrs`:'Not provided',relevant=c.relevantExperience!==''&&c.relevantExperience!=null?`Relevant: ${esc(c.relevantExperience)} yrs`:'';return `<tr data-candidate-id="${esc(c.id)}"><td class="candidate-primary"><strong title="${esc(c.name||'Candidate')}">${esc(c.name||'Candidate')}</strong><small title="${esc(c.designation||'Designation not provided')}">${esc(c.designation||'Designation not provided')}</small><small title="${esc(c.currentCompany||'')}">${esc(c.currentCompany||'')}</small></td><td class="candidate-contact"><span title="${esc(c.email||'Email not provided')}">${esc(c.email||'Email not provided')}</span><small title="${esc(c.phone||'Phone not provided')}">${esc(c.phone||'Phone not provided')}</small></td><td><span>${experience}</span>${relevant?`<small>${relevant}</small>`:''}</td><td><span title="${esc(c.location||'Location not provided')}">${esc(c.location||'Not provided')}</span>${c.preferredLocation?`<small title="Preferred: ${esc(c.preferredLocation)}">Preferred: ${esc(c.preferredLocation)}</small>`:''}</td><td>${esc(c.noticePeriod||'Not provided')}</td><td>${candidateDate(last?.date||c.lastScreenedDate)}${history.length?`<small>${history.length} screening${history.length===1?'':'s'}</small>`:''}</td><td>${last?`${statusBadge(last.recommendation)}<small title="${esc(role||'Latest screening score')}">${esc(last.score??0)}/100${role?` · ${esc(role)}`:''}</small>`:'<span class="badge blue">Stored</span>'}</td><td class="candidate-actions"><div class="candidate-action-row"><button type="button" class="btn ghost candidate-view-resume" ${hasResume?'':`disabled title="Resume unavailable"`} data-candidate-id="${esc(c.id)}">${hasResume?'View Resume':'Resume Unavailable'}</button><button type="button" class="btn ghost candidate-edit" data-candidate-id="${esc(c.id)}">Edit Profile</button></div></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state">${candidateReviewOnly?'No candidates currently need review.':'No candidates match this search.'}</div>`;
  candidateTableWrap.innerHTML=reviewHead+table;
  queueMicrotask(()=>window.TSSSafeBackendFeatures?.enhanceCandidateTable?.());
}
function candidateById(id){return(db.candidates||[]).find(c=>String(c.id)===String(id)||String(c.serverId)===String(id))}
function setCandidateEditValue(id,value){const el=document.getElementById(id);if(el)el.value=value??''}
function openCandidateEditor(id){const c=candidateById(id),dialog=document.getElementById('candidateDialog');if(!c||!dialog)return;setCandidateEditValue('candidateEditId',c.id);setCandidateEditValue('candidateEditName',c.name);setCandidateEditValue('candidateEditEmail',c.email);setCandidateEditValue('candidateEditPhone',c.phone);setCandidateEditValue('candidateEditDesignation',c.designation);setCandidateEditValue('candidateEditCompany',c.currentCompany);setCandidateEditValue('candidateEditLocation',c.location);setCandidateEditValue('candidateEditPreferredLocation',c.preferredLocation);setCandidateEditValue('candidateEditExperience',c.totalExperience);setCandidateEditValue('candidateEditRelevantExperience',c.relevantExperience);setCandidateEditValue('candidateEditNotice',c.noticePeriod);setCandidateEditValue('candidateEditCTC',c.currentCTC);setCandidateEditValue('candidateEditExpectedCTC',c.expectedCTC);setCandidateEditValue('candidateEditSkills',(c.skills||[]).join(', '));setCandidateEditValue('candidateEditEducation',c.education);document.getElementById('candidateEditHint').textContent=c.resumeAvailable?`Resume on file: ${c.resumeFilename||'stored resume'}`:'No resume file is currently stored for this candidate.';dialog.showModal()}
function applyCandidateRow(target,row){Object.assign(target,{id:row.id||target.id,serverId:row.id||target.serverId,name:row.candidate_name||target.name,email:row.email||target.email||'',phone:row.phone||'',location:row.current_location||'',preferredLocation:row.preferred_location||'',totalExperience:row.total_experience??'',relevantExperience:row.relevant_experience??'',currentCompany:row.current_company||'',designation:row.current_designation||'',skills:row.skills||[],education:row.education||'',noticePeriod:row.notice_period||'',currentCTC:row.current_ctc||'',expectedCTC:row.expected_ctc||''})}
async function saveCandidateEdits(){const id=document.getElementById('candidateEditId')?.value,c=candidateById(id),button=document.getElementById('saveCandidateBtn');if(!c)return;const email=document.getElementById('candidateEditEmail').value.trim().toLowerCase();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter a valid email address');return}const phone=document.getElementById('candidateEditPhone').value.trim();const payload={name:document.getElementById('candidateEditName').value.trim(),email:email||c.email||'',phone,designation:document.getElementById('candidateEditDesignation').value.trim(),currentCompany:document.getElementById('candidateEditCompany').value.trim(),location:document.getElementById('candidateEditLocation').value.trim(),preferredLocation:document.getElementById('candidateEditPreferredLocation').value.trim(),totalExperience:document.getElementById('candidateEditExperience').value,relevantExperience:document.getElementById('candidateEditRelevantExperience').value,noticePeriod:document.getElementById('candidateEditNotice').value.trim(),currentCTC:document.getElementById('candidateEditCTC').value.trim(),expectedCTC:document.getElementById('candidateEditExpectedCTC').value.trim(),skills:splitSkills(document.getElementById('candidateEditSkills').value),education:document.getElementById('candidateEditEducation').value.trim()};if(!payload.name){toast('Candidate name is required');return}button.disabled=true;button.textContent='Saving…';try{if(window.TSSBackend?.enabled&&c.serverId){const row=await window.TSSBackend.updateCandidate(c.serverId,payload);applyCandidateRow(c,row)}else Object.assign(c,payload);localStorage.setItem(DB_KEY,JSON.stringify(db));renderAll();document.getElementById('candidateDialog').close();toast('Candidate profile saved')}catch(error){console.error(error);toast('Candidate update failed: '+(error.message||error))}finally{button.disabled=false;button.textContent='Save Candidate'}}
candidateSearch.oninput=e=>renderCandidates(e.target.value);
candidateTableWrap.addEventListener('click',event=>{const view=event.target.closest('.candidate-view-resume'),edit=event.target.closest('.candidate-edit'),clear=event.target.closest('.candidate-clear-review');if(view&&!view.disabled){const c=candidateById(view.dataset.candidateId);if(c)window.TSSSafeBackendFeatures?.viewResume?.(c)}if(edit)openCandidateEditor(edit.dataset.candidateId);if(clear)showAllCandidates()});
window.TSSCandidateRecords={showReviewCandidates,showAllCandidates,reviewableIds:reviewableCandidateIds};
document.getElementById('saveCandidateBtn')?.addEventListener('click',saveCandidateEdits);
function renderHistory(){historyWrap.innerHTML=db.screenings.length?`<div style="overflow:auto"><table class="data-table"><thead><tr><th>Date</th><th>Candidate</th><th>Requirement</th><th>Score</th><th>Recommendation</th><th>Recruiter Decision</th><th>Notes</th></tr></thead><tbody>${db.screenings.slice().reverse().map(s=>{const c=db.candidates.find(x=>x.id===s.candidateId),r=db.requirements.find(x=>x.id===s.requirementId);return `<tr><td>${new Date(s.date).toLocaleString()}</td><td><strong>${esc(c?.name||'Unknown')}</strong></td><td>${esc(r?.client||'')}<br><small>${esc(r?.title||'')}</small></td><td><strong>${s.score}/100</strong></td><td>${statusBadge(s.recommendation)}</td><td>${esc(s.recruiterDecision||'Pending')}</td><td>${esc(s.notes||'-')}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty-state">No screening history yet</div>'}
function renderAll(){renderDashboard();renderSidebar();renderRequirements();populateScreenReq();renderCandidates(candidateSearch?.value||'');renderHistory()}
function roleSkillSuggestions(title,industry){const t=norm(title+' '+industry);const maps=[[/\.net|angular|developer|software/,['C#','ASP.NET Core','REST API','SQL','Git','Unit Testing','Debugging','Agile']],[/database|sql/,['SQL Server','MySQL','Stored Procedures','Query Optimization','Database Design','Indexing','Performance Tuning','ETL']],[/sales|business development|bdm/,['B2B Sales','Lead Generation','Client Acquisition','Negotiation','CRM','Pipeline Management','Revenue Targeting','Stakeholder Management']],[/manager|service/,['Team Leadership','Service Management','Customer Handling','Escalation Management','SLA Management','MIS Reporting','Process Improvement','Stakeholder Management']],[/data engineer/,['Python','SQL','ETL','Data Warehousing','Spark','Cloud','Airflow','Data Modeling']]];for(const [re,skills] of maps)if(re.test(t))return skills;return ['Communication','Stakeholder Management','Problem Solving','Domain Knowledge','Reporting','Process Management','Team Collaboration','Analytical Skills']}
function parseJDText(txt){const lower=txt.toLowerCase(),loc=(txt.match(/(?:location|based at|work location)[:\- ]+([^\n,]+)/i)||[])[1]||'',exp=(txt.match(/(\d+\+?\s*(?:-|to)?\s*\d*\s*years?)/i)||[])[1]||'',qual=(txt.match(/(?:qualification|education)[:\- ]+([^\n]+)/i)||[])[1]||'';const common=['Java','Spring Boot','Angular','React','Node.js','Python','SQL','MySQL','MS SQL','AWS','Azure','Docker','Kubernetes','C#','ASP.NET Core','REST API','CRM','B2B Sales','Team Leadership','Service Management','Power BI','Tableau','Excel'];const skills=common.filter(s=>lower.includes(s.toLowerCase()));return {location:loc.trim(),experience:exp.trim(),qualification:qual.trim(),skills}}
const dlg=document.getElementById('requirementDialog');addRequirementBtn.onclick=()=>openRequirement();function openRequirement(id){requirementForm.reset();reqId.value='';suggestedSkills.innerHTML='';const r=id?db.requirements.find(x=>x.id===id):null;if(r){reqId.value=r.id;reqClient.value=r.client;reqTitle.value=r.title;reqLocation.value=r.location||'';reqExperience.value=r.experience||'';reqIndustry.value=r.industry||'';reqJdText.value=r.jdText||'';reqSkills.value=(r.skills||[]).join(', ');reqPreferred.value=(r.preferred||[]).join(', ');reqQualification.value=r.qualification||'';reqResponsibilities.value=r.responsibilities||''}dlg.showModal()}
generateSkillsBtn.onclick=()=>{const s=roleSkillSuggestions(reqTitle.value,reqIndustry.value);suggestedSkills.innerHTML=s.map(x=>`<button type="button" class="skill ai suggest-chip" data-skill="${esc(x)}">${esc(x)} · AI Suggested</button>`).join('');document.querySelectorAll('.suggest-chip').forEach(b=>b.onclick=()=>{const cur=splitSkills(reqSkills.value);if(!cur.includes(b.dataset.skill))reqSkills.value=[...cur,b.dataset.skill].join(', ')})};
reqJdText.addEventListener('change',()=>{const p=parseJDText(reqJdText.value);if(!reqLocation.value&&p.location)reqLocation.value=p.location;if(!reqExperience.value&&p.experience)reqExperience.value=p.experience;if(!reqQualification.value&&p.qualification)reqQualification.value=p.qualification;if(!reqSkills.value&&p.skills.length)reqSkills.value=p.skills.join(', ')});
jdFile.onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.type==='text/plain'||f.name.endsWith('.txt')){const txt=await f.text();reqJdText.value=txt;reqJdText.dispatchEvent(new Event('change'));toast('JD text extracted')}else toast('File attached. For PDF/DOC demo, paste JD text for extraction.')};
saveRequirementBtn.onclick=()=>{if(!reqClient.value.trim()||!reqTitle.value.trim()){toast('Client and Job Title are required');return}const existing=reqId.value?db.requirements.find(x=>x.id===reqId.value):null;const id=existing?.id||`TSS${String(db.requirements.length+1).padStart(3,'0')}`;const manual=splitSkills(reqSkills.value),suggest=roleSkillSuggestions(reqTitle.value,reqIndustry.value),r={id,client:reqClient.value.trim(),title:reqTitle.value.trim(),location:reqLocation.value.trim(),experience:reqExperience.value.trim(),industry:reqIndustry.value.trim(),status:existing?.status||'Active',skills:manual.length?manual:suggest,preferred:splitSkills(reqPreferred.value),qualification:reqQualification.value.trim(),responsibilities:reqResponsibilities.value.trim(),jdText:reqJdText.value,aiSuggested:!manual.length};if(existing)Object.assign(existing,r);else db.requirements.push(r);db.activity.push({date:new Date().toISOString(),title:existing?'Requirement updated':'Requirement created',detail:`${r.client} — ${r.title}`});saveDB();dlg.close();toast(existing?'Requirement updated':'Requirement added');rematchRequirement(r)};
function rematchRequirement(r){const matches=db.candidates.map(c=>({c,s:scoreCandidate(c.resumeText||'',r,c).score})).filter(x=>x.s>=55);if(matches.length)toast(`${matches.length} existing CV match${matches.length>1?'es':''} found for ${r.title}`)}
resumeFile.onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.type==='text/plain'||f.name.endsWith('.txt')){resumeText.value=await f.text();toast('Resume text loaded')}else toast('Resume attached. Paste resume text for full demo screening.')};
function scoreCandidate(text,r,c={}){const hay=norm(`${text} ${c.designation||''} ${c.location||''}`);const mandatory=r.skills||[],preferred=r.preferred||[];const matched=mandatory.filter(s=>hay.includes(norm(s).trim())||tokens(s).some(t=>hay.includes(t))),missing=mandatory.filter(s=>!matched.includes(s));const prefMatched=preferred.filter(s=>hay.includes(norm(s).trim())||tokens(s).some(t=>hay.includes(t)));const mandatoryPct=mandatory.length?matched.length/mandatory.length*100:70,prefPct=preferred.length?prefMatched.length/preferred.length*100:70;const reqYears=parseFloat((r.experience||'').match(/[\d.]+/)?.[0]||0),candYears=parseFloat(c.totalExperience||0),expPct=reqYears?Math.min(100,candYears/reqYears*100):75;const titleTokens=tokens(r.title),rolePct=titleTokens.length?titleTokens.filter(t=>hay.includes(t)).length/titleTokens.length*100:60;const locPct=!r.location||!c.location?70:(norm(c.location).includes(norm(r.location))||norm(r.location).includes(norm(c.location))?100:45);const respTokens=tokens(r.responsibilities).filter(t=>t.length>4),domainPct=respTokens.length?Math.min(100,respTokens.filter(t=>hay.includes(t)).length/Math.min(respTokens.length,12)*100):65;let score=Math.round(mandatoryPct*.38+prefPct*.1+expPct*.2+rolePct*.1+domainPct*.12+locPct*.1);score=Math.max(15,Math.min(98,score));return {score,matched,missing,prefMatched,mandatoryPct:Math.round(mandatoryPct),prefPct:Math.round(prefPct),expPct:Math.round(expPct),domainPct:Math.round(domainPct),locPct:Math.round(locPct)}}
function detectDuplicate(email,phone,text){return db.candidates.find(c=>(email&&c.email&&norm(c.email)===norm(email))||(phone&&c.phone&&c.phone.replace(/\D/g,'')===phone.replace(/\D/g,''))||(text&&c.resumeHash===simpleHash(text)))}function simpleHash(str){let h=0;for(let i=0;i<str.length;i++)h=((h<<5)-h)+str.charCodeAt(i)|0;return String(h)}
screenBtn.onclick=()=>{const r=db.requirements.find(x=>x.id===screenRequirement.value);if(!r){toast('Select requirement');return}const text=resumeText.value.trim();if(!candidateName.value.trim()||!text){toast('Candidate name and resume text are required');return}const payload={name:candidateName.value.trim(),email:candidateEmail.value.trim(),phone:candidatePhone.value.trim(),totalExperience:candidateExp.value,location:candidateLocation.value.trim(),designation:candidateDesignation.value.trim(),noticePeriod:candidateNotice.value.trim(),currentCTC:candidateCTC.value.trim(),expectedCTC:candidateExpectedCTC.value.trim(),resumeText:text,resumeHash:simpleHash(text),uploadDate:new Date().toISOString(),uploadedBy:'Recruiter'};let c=detectDuplicate(payload.email,payload.phone,payload.resumeText);if(c){Object.assign(c,{...payload,id:c.id,uploadDate:c.uploadDate});toast('Duplicate candidate detected — existing profile reused')}else{c={id:`C${Date.now()}`,...payload};db.candidates.push(c)}const result=scoreCandidate(text,r,c);c.lastScreenedDate=new Date().toISOString();const rec=screeningLabel(result.score),s={id:`S${Date.now()}`,candidateId:c.id,requirementId:r.id,date:new Date().toISOString(),score:result.score,recommendation:rec,matched:result.matched,missing:result.missing,metrics:result,recruiterDecision:'Pending',notes:'',manualOverride:false};db.screenings.push(s);db.activity.push({date:s.date,title:'Candidate screened',detail:`${c.name} — ${r.title} — ${result.score}/100`});saveDB();showResult(s,c,r);toast('Screening complete')};
function showResult(s,c,r){screeningEmpty.classList.add('hidden');screeningResult.classList.remove('hidden');const m=s.metrics;screeningResult.innerHTML=`<div class="result-score"><div class="score-ring" style="--score:${s.score*3.6}deg"><strong>${s.score}</strong></div><div><span class="eyebrow">OVERALL MATCH</span><h3 style="margin:5px 0">${esc(c.name)}</h3>${statusBadge(s.recommendation)}<p style="color:var(--muted);font-size:12px">${esc(r.client)} · ${esc(r.title)}</p></div></div><div class="metric-grid"><div class="metric"><small>Mandatory Skill Match</small><strong>${m.mandatoryPct}%</strong></div><div class="metric"><small>Preferred Skill Match</small><strong>${m.prefPct}%</strong></div><div class="metric"><small>Experience Match</small><strong>${m.expPct}%</strong></div><div class="metric"><small>Domain Match</small><strong>${m.domainPct}%</strong></div><div class="metric"><small>Location Match</small><strong>${m.locPct}%</strong></div><div class="metric"><small>Recommendation</small><strong>${s.recommendation}</strong></div></div><div class="notes-box"><strong>Matching Skills</strong><div class="skill-cloud">${s.matched.map(x=>`<span class="skill">${esc(x)}</span>`).join('')||'<small>No exact keyword matches</small>'}</div></div><div class="notes-box"><strong>Missing / Unconfirmed Skills</strong><div class="skill-cloud">${s.missing.map(x=>`<span class="skill ai">${esc(x)}</span>`).join('')||'<small>No major mandatory gaps detected</small>'}</div></div><div class="notes-box"><strong>Clear Screening Explanation</strong><p style="color:var(--muted);font-size:13px">${explain(s,c,r)}</p></div><label>Recruiter Notes</label><textarea id="resultNotes" rows="3" placeholder="Add recruiter notes..."></textarea><div class="notes-box screening-save-panel" id="screeningSavePanel" style="display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap"><div><strong>Save this candidate</strong><p id="screeningSaveHint" style="color:var(--muted);font-size:12px;margin:5px 0 0">${s.serverId?'Candidate, CV and screening are stored securely.':'Score is ready. Save to add this candidate to Todo and the recruiter record.'}</p></div><button type="button" class="btn primary" id="saveScreenedCandidate" ${s.serverId?'disabled':''}>${s.serverId?'✓ Candidate Saved':'Save Candidate'}</button></div><div class="manual-actions"><button class="btn primary decision" data-d="Shortlisted">Shortlist</button><button class="btn ghost decision" data-d="Keep for Future">Keep for Future</button><button class="btn ghost decision" data-d="Request Updated Resume">Request Updated Resume</button><button class="btn ghost decision" data-d="Rejected">Reject</button><button class="btn ghost" id="approveAi">Approve AI Result</button><button class="btn ghost" id="editScore">Edit Score</button></div>`;document.querySelectorAll('.decision').forEach(b=>b.onclick=()=>updateDecision(s.id,b.dataset.d));approveAi.onclick=()=>updateDecision(s.id,'AI Result Approved');editScore.onclick=()=>{const n=prompt('Enter recruiter score (0-100)',s.score);if(n!==null&&!isNaN(n)){s.score=Math.max(0,Math.min(100,Number(n)));s.recommendation=screeningLabel(s.score);s.manualOverride=true;s.notes=resultNotes.value;saveDB();showResult(s,c,r);toast('Score manually updated')}}}
function explain(s,c,r){const strengths=[];if(s.metrics.mandatoryPct>=70)strengths.push('strong mandatory skill coverage');if(s.metrics.expPct>=90)strengths.push('experience meets the requirement');if(s.metrics.domainPct>=55)strengths.push('resume context overlaps with the role responsibilities');const concerns=[];if(s.missing.length)concerns.push(`${s.missing.length} mandatory skill(s) are not clearly evidenced`);if(s.metrics.locPct<60)concerns.push('location may need recruiter confirmation');return `The candidate scores ${s.score}/100 based on skills, experience, role relevance, domain context and location. ${strengths.length?'Strengths include '+strengths.join(', ')+'. ':''}${concerns.length?'Key concerns: '+concerns.join('; ')+'. ':''}This result does not reject candidates only on keyword differences; contextual and related terms are considered.`}
function updateDecision(id,d){const s=db.screenings.find(x=>x.id===id);s.recruiterDecision=d;s.notes=document.getElementById('resultNotes')?.value||s.notes;s.manualOverride=d!=='AI Result Approved';db.activity.push({date:new Date().toISOString(),title:'Recruiter decision',detail:`${d} — screening ${id}`});saveDB();toast(`Decision saved: ${d}`)}
exportBtn.onclick=()=>{const headers=['Client Name','Job Title','Candidate Name','Email','Phone','Location','Total Experience','Relevant Experience','Current Designation','Match Score','Recommendation','Matching Skills','Missing Skills','Notice Period','Recruiter Decision','Recruiter Notes','Screening Date'];const rows=db.screenings.map(s=>{const c=db.candidates.find(x=>x.id===s.candidateId)||{},r=db.requirements.find(x=>x.id===s.requirementId)||{};return [r.client,r.title,c.name,c.email,c.phone,c.location,c.totalExperience,'',c.designation,s.score,s.recommendation,(s.matched||[]).join('; '),(s.missing||[]).join('; '),c.noticePeriod,s.recruiterDecision,s.notes,new Date(s.date).toLocaleString()]});const csv=[headers,...rows].map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`TSS_Screening_Export_${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Excel-compatible export downloaded')};
const openRequirementBase=openRequirement;
openRequirement=function(id){
  openRequirementBase(id);
  const r=id?db.requirements.find(x=>x.id===id):null;
  reqStatus.value=['Work In Progress','On Hold','Closed','Fulfilled'].includes(r?.status)?r.status:'Work In Progress';
};
saveRequirementBtn.addEventListener('click',()=>{
  if(window.TSSBackend?.enabled)return;
  const r=reqId.value?db.requirements.find(x=>x.id===reqId.value):db.requirements.at(-1);
  if(r){r.status=reqStatus.value||'Work In Progress';saveDB();renderAll();}
});
renderAll();

